CREATE TYPE "RevisionStatus" AS ENUM ('DRAFT','REVIEW','PUBLISHED','RETIRED');
CREATE TYPE "RoleName" AS ENUM ('ADMIN','EDITOR','REVIEWER');
CREATE TABLE "Specialty" ("id" TEXT PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL);
CREATE TABLE "Topic" ("id" TEXT PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"title" TEXT NOT NULL,"summary" TEXT,"specialtyId" TEXT NOT NULL REFERENCES "Specialty"("id"),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "Role" ("id" TEXT PRIMARY KEY,"name" "RoleName" NOT NULL UNIQUE);
CREATE TABLE "UserRole" ("userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"roleId" TEXT NOT NULL REFERENCES "Role"("id") ON DELETE CASCADE,PRIMARY KEY("userId","roleId"));
CREATE TABLE "ContentRevision" ("id" TEXT PRIMARY KEY,"topicId" TEXT NOT NULL REFERENCES "Topic"("id") ON DELETE CASCADE,"version" INTEGER NOT NULL,"content" TEXT NOT NULL,"format" TEXT NOT NULL DEFAULT 'mdx',"status" "RevisionStatus" NOT NULL DEFAULT 'DRAFT',"authorId" TEXT NOT NULL REFERENCES "User"("id"),"approvedById" TEXT REFERENCES "User"("id"),"approvedAt" TIMESTAMP(3),"reviewDueAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("topicId","version"));
CREATE INDEX "ContentRevision_status_createdAt_idx" ON "ContentRevision"("status","createdAt");
CREATE TABLE "Reference" ("id" TEXT PRIMARY KEY,"revisionId" TEXT NOT NULL REFERENCES "ContentRevision"("id") ON DELETE CASCADE,"title" TEXT NOT NULL,"url" TEXT,"citation" TEXT);
CREATE TABLE "Favorite" ("userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"topicId" TEXT NOT NULL REFERENCES "Topic"("id") ON DELETE CASCADE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("userId","topicId"));
CREATE TABLE "Note" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"topicId" TEXT NOT NULL REFERENCES "Topic"("id") ON DELETE CASCADE,"body" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "AuditEvent" ("id" TEXT PRIMARY KEY,"actorId" TEXT NOT NULL REFERENCES "User"("id"),"revisionId" TEXT REFERENCES "ContentRevision"("id"),"action" TEXT NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "AuditEvent_createdAt_idx" ON "AuditEvent"("createdAt");
